struct Token {
    static inline int live = 0;
    int id;

    explicit Token(int value) : id(value) {
        if (value == 3) {
            throw std::runtime_error{"unterminated string"};
        }
        ++live;
    }
    ~Token() { --live; }
};

int main() {
    alignas(Token) std::byte scratch[3 * sizeof(Token)];
    auto* base = reinterpret_cast<Token*>(scratch);

    int built = 0;
    try {
        for (int value = 1; value <= 3; ++value) {
            std::construct_at(base + built, value);
            ++built;
        }
    } catch (const std::runtime_error&) {
        std::destroy_n(base, built);
    }

    std::cout << built << ' ' << Token::live << '\n';
}

