class BumpArena {
public:
    BumpArena(std::byte* data, std::size_t capacity) noexcept
        : data_(data), capacity_(capacity) {}

    void* take(std::size_t bytes, std::size_t alignment) noexcept {
        const std::size_t start = (used_ + alignment - 1) & ~(alignment - 1);
        if (start + bytes > capacity_) {
            return nullptr;
        }
        used_ = start + bytes;
        return data_ + start;
    }

    std::size_t used() const noexcept { return used_; }

private:
    std::byte* data_;
    std::size_t capacity_;
    std::size_t used_{};
};

struct AstNode {
    std::uint64_t payload;
};

int main() {
    alignas(8) std::byte block[128];
    BumpArena arena{block, sizeof(block)};

    arena.take(1, 1);  // a one-byte node tag
    void* node = arena.take(sizeof(AstNode), alignof(AstNode));
    arena.take(2, 2);  // a two-byte source offset

    std::cout << arena.used() << ' '
              << (reinterpret_cast<std::uintptr_t>(node) % alignof(AstNode) == 0)
              << '\n';
}

