#include <cstddef>
#include <cstdint>
#include <memory>
#include <span>
#include <stdexcept>

template <class T>
T* fill_raw(std::span<std::byte> storage, std::size_t count, const T& value) {
    if (count > storage.size() / sizeof(T)) {
        throw std::length_error{"scratch buffer too small"};
    }
    if (reinterpret_cast<std::uintptr_t>(storage.data()) % alignof(T) != 0) {
        throw std::invalid_argument{"scratch buffer is misaligned for T"};
    }

    T* first = reinterpret_cast<T*>(storage.data());
    std::size_t built = 0;
    try {
        for (; built < count; ++built) {
            std::construct_at(first + built, value);
        }
    } catch (...) {
        std::destroy_n(first, built);  // the failed element is not one of them
        throw;
    }
    return first;
}

