struct AtlasRow {
    std::uint32_t top;
    std::uint32_t height;
};

class RowStore {
public:
    explicit RowStore(std::size_t rows) {
        if (!reserve(rows)) {
            throw std::bad_alloc{};
        }
    }

    RowStore(const RowStore&) = delete;
    RowStore& operator=(const RowStore&) = delete;

    RowStore(RowStore&& other) noexcept
        : rows_(std::exchange(other.rows_, nullptr)),
          capacity_(std::exchange(other.capacity_, 0)) {}

    RowStore& operator=(RowStore&& other) noexcept {
        if (this != &other) {
            std::free(rows_);
            rows_ = std::exchange(other.rows_, nullptr);
            capacity_ = std::exchange(other.capacity_, 0);
        }
        return *this;
    }

    ~RowStore() { std::free(rows_); }

    AtlasRow* data() noexcept { return rows_; }
    std::size_t capacity() const noexcept { return capacity_; }

    bool reserve(std::size_t rows) {
        if (rows <= capacity_) {
            return true;
        }
        if (rows > std::numeric_limits<std::size_t>::max() / sizeof(AtlasRow)) {
            return false;
        }

        void* grown = std::realloc(rows_, rows * sizeof(AtlasRow));
        if (grown == nullptr) {
            return false;  // the old block is still allocated and still ours
        }
        rows_ = static_cast<AtlasRow*>(grown);
        capacity_ = rows;
        return true;
    }

private:
    AtlasRow* rows_ = nullptr;
    std::size_t capacity_ = 0;
};

#include <cstddef>
#include <cstdint>
#include <new>
#include <vector>

struct Event {
    std::uint64_t timestamp;
    std::uint32_t code;
};

class EventSink {
public:
    explicit EventSink(std::size_t slots) : slots_(slots), free_(slots) {
        for (std::size_t i = 0; i < slots; ++i) {
            free_[i] = i;
        }
    }

    // Exhaustion policy: acquire reports failure by returning nullptr. The
    // caller drops the event and increments a counter; it must not fall back
    // to the global allocator while the session is live.
    Event* acquire() noexcept {
        if (free_count_ == 0) {
            return nullptr;
        }
        return &slots_[free_[--free_count_]];
    }

    void release(Event* event) noexcept {
        free_[free_count_++] = static_cast<std::size_t>(event - slots_.data());
    }

private:
    std::vector<Event> slots_;
    std::vector<std::size_t> free_;
    std::size_t free_count_ = 0;
};

bool preallocate(EventSink*& sink, std::size_t slots) noexcept {
    sink = new (std::nothrow) EventSink{slots};
    return sink != nullptr;
}

