template <class T>
class ScratchCell {
public:
    ScratchCell() = default;
    ScratchCell(const ScratchCell&) = delete;
    ScratchCell& operator=(const ScratchCell&) = delete;
    ~ScratchCell() { reset(); }

    template <class... Args>
    T& emplace(Args&&... args) {
        reset();
        // engaged_ is already false here, so a throwing constructor leaves the
        // cell empty and the destructor will not run on a nonexistent object.
        T* object = std::construct_at(pointer(), std::forward<Args>(args)...);
        engaged_ = true;
        return *object;
    }

    void reset() noexcept {
        if (engaged_) {
            std::destroy_at(pointer());
            engaged_ = false;
        }
    }

    bool engaged() const noexcept { return engaged_; }

    T& get() {
        if (!engaged_) {
            throw std::logic_error{"scratch cell is empty"};
        }
        return *pointer();
    }

private:
    T* pointer() noexcept { return reinterpret_cast<T*>(storage_); }

    alignas(T) std::byte storage_[sizeof(T)];
    bool engaged_ = false;
};

