struct MeshChunk {
    float bounds[6];

    // bytes is not always sizeof(MeshChunk): a derived class inherits this
    // allocation function, and new Derived asks for sizeof(Derived).
    static void* operator new(std::size_t bytes) {
        return ChunkMemory::allocate(bytes);
    }
    static void* operator new[](std::size_t bytes) {
        return ChunkMemory::allocate(bytes);
    }

    static void operator delete(void* block) noexcept {
        ChunkMemory::deallocate(block, 0);
    }
    static void operator delete(void* block, std::size_t bytes) noexcept {
        ChunkMemory::deallocate(block, bytes);
    }
    static void operator delete[](void* block) noexcept {
        ChunkMemory::deallocate(block, 0);
    }
    static void operator delete[](void* block, std::size_t bytes) noexcept {
        ChunkMemory::deallocate(block, bytes);
    }
};

