#include <stdexcept>

template <class T>
T* allocate_over_aligned(std::size_t count, std::size_t alignment) {
    if (alignment == 0 || (alignment & (alignment - 1)) != 0) {
        throw std::invalid_argument{"alignment must be a power of two"};
    }
    if (count > std::numeric_limits<std::size_t>::max() / sizeof(T)) {
        throw std::bad_alloc{};
    }

    void* storage = ::operator new(count * sizeof(T),
                                   std::align_val_t{alignment});
    return static_cast<T*>(storage);
}

template <class T>
void release_over_aligned(T* block, std::size_t count,
                          std::size_t alignment) noexcept {
    ::operator delete(block, count * sizeof(T),
                      std::align_val_t{alignment});
}

#include <cstddef>
#include <cstdint>
#include <cstring>
#include <span>
#include <stdexcept>

class SlotRecycler {
public:
    SlotRecycler(std::span<std::byte> storage, std::size_t block_size,
                 std::size_t block_alignment)
        : block_size_(block_size) {
        if (block_size < sizeof(std::byte*)) {
            throw std::invalid_argument{"block cannot hold a free-list link"};
        }
        if (block_alignment == 0 ||
            (block_alignment & (block_alignment - 1)) != 0) {
            throw std::invalid_argument{"alignment must be a power of two"};
        }

        const auto base = reinterpret_cast<std::uintptr_t>(storage.data());
        const std::uintptr_t mask = block_alignment - 1;
        const std::size_t skipped =
            static_cast<std::size_t>(((base + mask) & ~mask) - base);
        if (skipped >= storage.size()) {
            return;  // nothing usable; capacity stays zero
        }

        std::byte* first = storage.data() + skipped;
        capacity_ = (storage.size() - skipped) / block_size;
        for (std::size_t i = capacity_; i-- > 0;) {
            std::byte* block = first + i * block_size;
            std::memcpy(block, &head_, sizeof(head_));  // link, no union
            head_ = block;
        }
    }

    void* allocate() noexcept {
        if (head_ == nullptr) {
            return nullptr;
        }
        std::byte* block = head_;
        std::memcpy(&head_, block, sizeof(head_));
        return block;
    }

    void deallocate(void* block) noexcept {
        auto* slot = static_cast<std::byte*>(block);
        std::memcpy(slot, &head_, sizeof(head_));
        head_ = slot;
    }

    std::size_t capacity() const noexcept { return capacity_; }

private:
    std::size_t block_size_;
    std::size_t capacity_ = 0;
    std::byte* head_ = nullptr;
};
